// Breadcrumb rendering tests.
//
// Generated by hsg:collection-breadcrumbs() in modules/templates/hsg.xqm:
// always Home > Historical Documents > volume title (linked, except on the
// volume landing page itself, where it's the current crumb). On a
// chapter/compilation/document page, one more crumb is appended as the
// current (non-link) one, on its own line: the division's own title for a
// chapter/compilation, or "Document <n>" for a document.
//
// baseUrl is http://localhost:8080/exist/apps/hsg-jinks (cypress.config.cjs),
// which matches the container's default host port mapping. If you remapped the
// host port (see "Remapping ports" in the README), override it:
// `cypress run --config baseUrl=http://localhost:<host-port>/exist/apps/hsg-jinks`.

const VOLUME = "historicaldocuments/frus1981-88v05";
const VOLUME_TITLE =
    "Foreign Relations of the United States, 1981–1988, Volume V, Soviet Union, March 1985–October 1986";

function crumbTexts() {
    return cy
        .get('nav[aria-label="breadcrumb"] ul:not(:empty) li')
        .then(($lis) => Cypress._.map($lis, (li) => li.textContent.replace(/\s+/g, " ").trim()));
}

function lastCrumb() {
    return cy.get('nav[aria-label="breadcrumb"] ul:not(:empty) li').last();
}

describe("breadcrumb", () => {
    it("volume landing page: Home > Historical Documents > volume title (current, not a link)", () => {
        cy.visit(VOLUME);
        crumbTexts().should("deep.equal", ["Home", "Historical Documents", VOLUME_TITLE]);
        lastCrumb().should("have.attr", "aria-current", "page").find("a").should("not.exist");
    });

    // The volume landing page has a TOC in the before sidebar, making
    // pb-page's grid "before-fixed" (see templates/layouts/hsg-content.html).
    // .content-top must then span across the sidebar's column (profile-
    // theme-uswds layout.css) so the toolbar/breadcrumb row lines up with the
    // page-header's left edge instead of stopping at the sidebar.
    it("volume landing page: breadcrumb aligns flush with the page header's left edge", () => {
        cy.visit(VOLUME);
        cy.get(".usa-logo").then(($logo) => {
            const logoLeft = $logo[0].getBoundingClientRect().left;
            cy.get('nav[aria-label="breadcrumb"]').should(($nav) => {
                // Tolerance is half a classic scrollbar (8px), not 1px --
                // same vw-vs-scrollbar limitation of the header's full-bleed
                // escape as documented in page-width-alignment.cy.js.
                expect($nav[0].getBoundingClientRect().left).to.be.closeTo(logoLeft, 8);
            });
        });
    });

    it("compilation page: current crumb is the compilation's own title, on its own line", () => {
        cy.visit(`${VOLUME}/comp`);
        crumbTexts().should("deep.equal", [
            "Home",
            "Historical Documents",
            VOLUME_TITLE,
            "Soviet Union, March 1985–October 1986",
        ]);
        lastCrumb().should("have.attr", "aria-current", "page").and("have.css", "display", "block");
    });

    it("chapter page: current crumb is the chapter's own title, on its own line", () => {
        cy.visit(`${VOLUME}/ch1`);
        crumbTexts().should("deep.equal", [
            "Home",
            "Historical Documents",
            VOLUME_TITLE,
            // Space between date-range title and subtitle (OP#1085); the
            // block contexts (heading, TOCs) line-break instead, covered by
            // chapter-title-split.cy.js.
            "March 1985–July 1985 “Now we have to begin everything anew”: Gorbachev’s Debut",
        ]);
        lastCrumb().should("have.attr", "aria-current", "page").and("have.css", "display", "block");
    });

    it("document page: current crumb reads \"Document <n>\", on its own line", () => {
        cy.visit(`${VOLUME}/d1`);
        crumbTexts().should("deep.equal", ["Home", "Historical Documents", VOLUME_TITLE, "Document 1"]);
        lastCrumb().should("have.attr", "aria-current", "page").and("have.css", "display", "block");
    });

    it("volume title links back to the landing page on every interior page", () => {
        cy.visit(`${VOLUME}/comp`);
        cy.get('nav[aria-label="breadcrumb"] ul:not(:empty) li')
            .eq(2)
            .find("a")
            .should("have.attr", "href")
            .and("match", new RegExp(`/${VOLUME}$`));
    });

    it("Home crumb links to the site root", () => {
        cy.visit(VOLUME);
        cy.get('nav[aria-label="breadcrumb"] ul:not(:empty) li')
            .first()
            .find("a")
            .should("have.attr", "href")
            .and("match", /\/$/);
    });
});
